دالة هل_متوازنة(نص) {
    متغير قوس = مجموعة()
    متغير ع = ٠
    من_أجل (ح في نص) {
        إذا (ح == '(' أو ح == '[' أو ح == '{') {
            أضف(قوس، ح)
            ع = ع + ١
        } وإلا إذا (ح == ')' أو ح == ']' أو ح == '}') {
            إذا (ع == ٠) {
                ارجع خطأ
            } وإلا {
                انزع(قوس)
                ع = ع - ١
            }
        }
    }
    إذا (ع == ٠) {
        ارجع صحيح
    } وإلا {
        ارجع خطأ
    }
}
